import { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, BorderStyle, HeadingLevel } from "docx";
import { writeFileSync } from "fs";

const reservation = {
  "Confirmation Number": "B75309",
  "Trip Type": "One-way, Economy",
  "From": "LAX (Los Angeles)",
  "To": "LAS (Las Vegas)",
  "Date": "2026-09-16",
  "Flight": "FL398507",
  "Amount Paid": "$129.00",
  "Payment Method": "Visa credit card ending in cc_9cdfc95d",
};

const borderStyle = {
  style: BorderStyle.SINGLE,
  size: 1,
  color: "999999",
};
const borders = {
  top: borderStyle,
  bottom: borderStyle,
  left: borderStyle,
  right: borderStyle,
};

const tableRows = Object.entries(reservation).map(
  ([key, value]) =>
    new TableRow({
      children: [
        new TableCell({
          borders,
          width: { size: 3000, type: WidthType.DXA },
          children: [
            new Paragraph({
              children: [new TextRun({ text: key, bold: true })],
            }),
          ],
        }),
        new TableCell({
          borders,
          width: { size: 6000, type: WidthType.DXA },
          children: [new Paragraph({ children: [new TextRun(value)] })],
        }),
      ],
    })
);

const doc = new Document({
  sections: [
    {
      children: [
        new Paragraph({
          heading: HeadingLevel.HEADING_1,
          children: [new TextRun({ text: "Travel Summary" })],
        }),
        new Paragraph({ children: [] }),
        new Paragraph({
          heading: HeadingLevel.HEADING_2,
          children: [
            new TextRun({ text: "Airline Reservation — B75309" }),
          ],
        }),
        new Table({ rows: tableRows }),
      ],
    },
  ],
});

const buffer = await Packer.toBuffer(doc);
writeFileSync("docs/travel_summary.docx", buffer);
console.log("Created docs/travel_summary.docx");
